    /**
     * @param  bool  $fill  залить фигуру (кнопки «смотреть», «пауза»)
     */
    public static function svg(string $name, string $class = '', bool $fill = false): HtmlString
    {
        $nodes = self::NODES[$name] ?? '';

        return new HtmlString(sprintf(
            '<svg class="icon %s" viewBox="0 0 24 24" fill="%s" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">%s</svg>',
            e($class),
            $fill ? 'currentColor' : 'none',
            $nodes,
        ));
    }
